"""Loopback monitor: online loss and matched free-generation learning curves."""
from pathlib import Path
import sys
from toolcall_lab import live_progress

ROOT=Path.home()/'.local/share/local-tool-calling/runs/fields-epochs-20261116'
HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>600条 × 3轮 · 学习率对照</title><style>
body{font:15px system-ui;background:#101b24;color:#e6edf1;max-width:1320px;margin:32px auto;padding:0 22px;line-height:1.7}h1{font-size:30px}a{color:#8be7c3}.muted{color:#a7bdca}.row,.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:#1b2b36;border:1px solid #344954;border-radius:13px;padding:18px;margin:12px 0}.big{font-size:25px}progress{width:100%;accent-color:#72dbb6}svg{width:100%;height:210px}table{border-collapse:collapse;width:100%;white-space:nowrap}td,th{padding:9px;border-bottom:1px solid #344954;text-align:left}.scroll{overflow:auto}pre{white-space:pre-wrap;word-break:break-word;font-size:12px}.blue{color:#60b5f4}.orange{color:#f6b16f}#alert{color:#ffd198}@media(max-width:800px){.row,.grid{grid-template-columns:1fr}}
</style><h1>固定600条数据：学习率与训练轮数</h1><p class="muted">A = 1e-4 · B = 5e-5 · 相同数据、目标与顺序 · 各3轮 /225次更新 · 每轮固定训练120题 + 开发120题</p>
<div class="row"><div class="card">当前阶段<div id="stage" class="big">准备中</div><span id="status"></span></div><div class="card">当前阶段进度<div id="steps" class="big">—</div><progress id="bar"></progress></div><div class="card">累计时间<div id="elapsed" class="big">—</div><span id="updated" class="muted"></span></div></div><p id="alert"></p><p id="message"></p>
<div class="card"><b>在线训练 loss</b><svg id="loss" viewBox="0 0 600 210"></svg><p class="muted">每8条样本的监督token交叉熵均值，未平滑。A第1轮复用历史记录；两组训练目标相同。<span class="blue">蓝 A</span> / <span class="orange">橙 B</span>。</p></div>
<p>行为曲线：<span class="blue">蓝 A</span> / <span class="orange">橙 B</span>；实线=模型独立输出，虚线=模型字段＋确定性转换。未完成的轮次不画成0。</p><div class="grid" id="plots"></div>
<div class="card scroll"><b>每轮完整结果</b><table><thead><tr><th>学习率</th><th>轮次</th><th>题集</th><th>方式</th><th>完整 /60</th><th>缺参 /48</th><th>误追问 /60 ↓</th><th>猜参 /48 ↓</th><th>不支持 /12</th><th>总正确 /120</th><th>字段全对 /120</th></tr></thead><tbody id="cells"></tbody></table></div>
<div class="row"><div class="card"><b>资源与当前更新</b><pre id="metrics"></pre></div><div class="card"><b>审计</b><pre id="audit"></pre></div><div class="card"><b>固定题集 teacher-forced loss</b><pre id="teacher">每轮完成后显示。标准前文条件下的loss，不代表自由生成准确率。</pre></div></div><p id="result"></p><p class="muted">每5秒刷新 · 仅绑定本机127.0.0.1 · 封存测试不使用 · 单种子开发实验</p>
<script>
const $=x=>document.getElementById(x),NS='http://www.w3.org/2000/svg',colors={A:'#60b5f4',B:'#f6b16f'};
for(let split of ['dev','seen'])for(let [key,title] of [['C','完整任务正确率 ↑'],['Q','缺参精确识别率 ↑'],['F','误追问率 ↓']]){let el=document.createElement('div');el.className='card';el.innerHTML=`<b>${split==='dev'?'开发集':'已见训练'} · ${title}</b><svg id="${split}-${key}" viewBox="0 0 600 210"></svg>`;$('plots').append(el)}
function chart(id,series,xmax,ymax,percent=false){let svg=$(id);svg.replaceChildren();const add=(tag,attrs,text)=>{let e=document.createElementNS(NS,tag);for(let[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;svg.append(e);return e};for(let i=0;i<=4;i++){let y=180-i*38;add('line',{x1:48,x2:575,y1:y,y2:y,stroke:'#344954'});add('text',{x:42,y:y+4,fill:'#a7bdca','text-anchor':'end','font-size':12},percent?Math.round(i*ymax/4)+'%':(i*ymax/4).toFixed(2))}for(let i=0;i<=3;i++)add('text',{x:48+i*175,y:201,fill:'#a7bdca','font-size':12},String(Math.round(i*xmax/3)));for(let s of series){if(!s.points.length)continue;let p=s.points.map(v=>[48+v.x/xmax*525,180-v.y/ymax*152]);add('path',{d:p.map((v,i)=>`${i?'L':'M'}${v.join(',')}`).join(' '),fill:'none',stroke:s.color,'stroke-width':2,'stroke-dasharray':s.dashed?'7 5':''});for(let[x,y]of p)if(percent)add('circle',{cx:x,cy:y,r:3,fill:s.color})}}
async function refresh(){try{let response=await fetch('/api/state',{cache:'no-store'});if(!response.ok)throw Error(response.status);let s=await response.json();$('stage').textContent=s.detail||s.stage;$('status').textContent=s.status;$('steps').textContent=`${s.step||0} / ${s.total_steps||0}`;$('bar').max=s.total_steps||1;$('bar').value=s.step||0;$('message').textContent=s.message||'';$('elapsed').textContent=(((s.finished_at||Date.now()/1000)-s.started_at)/60).toFixed(1)+' 分钟';$('updated').textContent=new Date(s.updated_at*1000).toLocaleTimeString();$('alert').textContent=s.stale?'工作进程超过90秒未更新心跳，请检查状态。':'';$('metrics').textContent=JSON.stringify(s.metrics||{},null,2);$('audit').textContent=JSON.stringify(s.audit||{},null,2);
let loss=['A','B'].map(a=>({color:colors[a],points:(s['loss_'+a]||[]).map(e=>({x:e.optimizer_updates,y:e.loss}))}));chart('loss',loss,225,Math.max(.01,...loss.flatMap(x=>x.points.map(p=>p.y))));let cells=s.cells||[];
for(let split of ['dev','seen'])for(let k of ['C','Q','F']){let lines=[];for(let a of ['A','B'])for(let mode of ['model','D'])lines.push({color:colors[a],dashed:mode==='D',points:cells.filter(c=>c.arm===a&&c.split===split).sort((a,b)=>a.epoch-b.epoch).map(c=>({x:c.epoch,y:100*c[mode][k]/c[mode][k+'_n']}))});chart(split+'-'+k,lines,3,100,true)}
$('cells').replaceChildren();for(let c of cells)for(let mode of ['model','D']){let tr=document.createElement('tr');for(let v of [c.arm==='A'?'1e-4':'5e-5',c.epoch,c.split==='dev'?'开发':'已见训练',mode==='model'?'模型':'转换器',...['C','Q','F','P','U','success'].map(k=>c[mode][k]),c.fields.exact]){let td=document.createElement('td');td.textContent=v;tr.append(td)}$('cells').append(tr)}$('teacher').textContent=(s.teacher_cells||[]).map(c=>`${c.arm} /第${c.epoch}轮/${c.split}：loss ${c.loss.toFixed(5)}`).join('\n')||'等待每轮固定题集评测。';$('result').replaceChildren();if(s.results_ready){let a=document.createElement('a');a.href='/results';a.textContent='打开结果对比与解释 →';$('result').append(a)}}catch(e){$('alert').textContent='连接中断，保留最后已知数据。'}}refresh();setInterval(refresh,5000);
</script></html>'''

def main():
    live_progress.HTML=HTML;sys.argv=[sys.argv[0],'--root',str(ROOT),'--port','49415'];live_progress.main()

if __name__=='__main__':main()
